cd /tmp/sv-44f95074ec5d4d66889f4bc62b141eb0/moderate-msbuild-properties && dotnet package list --format json 2>/dev/null | python3 -c "
import json, sys
data = json.load(sys.stdin)
for p in data['projects']:
    name = p['path'].split('/')[-1]
    for fw in p['frameworks']:
        for pkg in fw['topLevelPackages']:
            print(f'{name} | {pkg[\"id\"]} | {pkg[\"resolvedVersion\"]}')
"

